interface DeepMergeOptions {
    excludeKeys?: (key: string) => boolean;
}
/**
 * 深度合并对象与数组，类实例仍按字段合并。Date、RegExp、Map、Set、缓冲区等内建数据对象
 * 作为字段值时会被新的值整体替换。
 * 如果某层级的 key 被过滤，则执行替换而不继续深度合并。
 *
 * 对象目标会被原地修改；两个数组合并时返回新数组，按索引合并并保留目标的多余项。
 *
 * @param target 合并目标
 * @param source 合并来源
 * @param options 合并配置
 * @returns 对象目标本身，或合并后的新数组
 */
export declare const deepMerge: <T extends object, U extends object>(target: T, source: U, options?: DeepMergeOptions) => T & U;
export {};
